/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_COMMON_ADDRESS
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_LOCATION   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 3 emitted of 4 (one per source view AND run)
   runs        : 2 -- opus_health_delta3, opus_health_v2
   payload     : 5 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_LOCATION_HK
   hashdiff    : SAT_COMMON_ADDRESS_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   BESPOKE LAYER dual_feed_satellite_loader (s6.5): BOTH runs write this satellite.
   The standard satellite layer unions feeders that are disjoint by construction,
   which is the assumption two independent writers break.
*/

with feeders as (
    select
        md5(upper('HUB_LOCATION|' || (HUB_LOCATION_BK__ADD_LINE1_ADD_LINE2_ADD_LINE3_ADD_LINE4_CITY_STATE_STATE_CODE_PINCODE))) as HUB_LOCATION_HK
        , cast(null as varchar) as SECONDARY_LANDMARK
        , ADD_REMARKS as ADDRESS_REMARKS
        , cast(null as varchar) as FULL_ADDRESS_TEXT
        , cast(null as varchar) as SOURCE_SYSTEM_ADDRESS_IDENTIFIER
        , cast(null as varchar) as CITY_CODE
        , 'BJAZ_BRANCH_MASTER' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_branch_master') }}
    where (md5(normalise(upper(nullif(trim( coalesce(ADD_LINE1,'') || '|' || coalesce(ADD_LINE2,'') || '|' || coalesce(ADD_LINE3,'') || '|' || coalesce(ADD_LINE4,'') || '|' || coalesce(CITY,'') || '|' || coalesce(STATE,'') || '|' || coalesce(STATE_CODE,'') || '|' || coalesce(PINCODE,'') ), '|||||||'))))) is not null
    union all
    select
        md5(upper('HUB_LOCATION|' || (HUB_LOCATION_BK__MANDATE_ADDRESS_AREA_CITY_STATE_PINCODE))) as HUB_LOCATION_HK
        , cast(null as varchar) as SECONDARY_LANDMARK
        , cast(null as varchar) as ADDRESS_REMARKS
        , MANDATE_ADDRESS as FULL_ADDRESS_TEXT
        , ADDRESS_ID as SOURCE_SYSTEM_ADDRESS_IDENTIFIER
        , cast(null as varchar) as CITY_CODE
        , 'BJAZ_NEFT_PARTNER_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_neft_partner_dtls') }}
    where (md5(normalise(upper(nullif(coalesce(trim(MANDATE_ADDRESS),'') || '|' || coalesce(trim(AREA),'') || '|' || coalesce(trim(CITY),'') || '|' || coalesce(trim(STATE),'') || '|' || coalesce(trim(to_char(PINCODE)),''), '||||'))))) is not null
    union all
    select
        md5(upper('HUB_LOCATION|' || (HUB_LOCATION_BK__MAILING_PINCODE))) as HUB_LOCATION_HK
        , cast(null as varchar) as SECONDARY_LANDMARK
        , cast(null as varchar) as ADDRESS_REMARKS
        , cast(null as varchar) as FULL_ADDRESS_TEXT
        , cast(null as varchar) as SOURCE_SYSTEM_ADDRESS_IDENTIFIER
        , CITY_CODE as CITY_CODE
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (md5(normalise(upper(nullif(trim(MAILING_PINCODE),''))))) is not null
),

resolved as (
    select
        HUB_LOCATION_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SECONDARY_LANDMARK end) as SECONDARY_LANDMARK,
        max(case when SOURCE_RUN = 'opus_health_v2' then ADDRESS_REMARKS end) as ADDRESS_REMARKS,
        max(case when SOURCE_RUN = 'opus_health_v2' then FULL_ADDRESS_TEXT end) as FULL_ADDRESS_TEXT,
        max(case when SOURCE_RUN = 'opus_health_v2' then SOURCE_SYSTEM_ADDRESS_IDENTIFIER end) as SOURCE_SYSTEM_ADDRESS_IDENTIFIER,
        max(case when SOURCE_RUN = 'opus_health_delta3' then CITY_CODE end) as CITY_CODE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_LOCATION_HK
),

hashed as (
    select
        *,
        case when SECONDARY_LANDMARK is not null or ADDRESS_REMARKS is not null or FULL_ADDRESS_TEXT is not null or SOURCE_SYSTEM_ADDRESS_IDENTIFIER is not null or CITY_CODE is not null
                     then md5(upper(coalesce(cast(SECONDARY_LANDMARK as varchar), '') || '|' || coalesce(cast(ADDRESS_REMARKS as varchar), '') || '|' || coalesce(cast(FULL_ADDRESS_TEXT as varchar), '') || '|' || coalesce(cast(SOURCE_SYSTEM_ADDRESS_IDENTIFIER as varchar), '') || '|' || coalesce(cast(CITY_CODE as varchar), '')))
                end as SAT_COMMON_ADDRESS_HASHDIFF
    from resolved
)

select * from hashed
where HUB_LOCATION_HK is not null
  and SAT_COMMON_ADDRESS_HASHDIFF is not null
